"""Register actual bounded source inspection, separate from original course design."""
import hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4];BASE=Path(__file__).resolve().parent
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,v):p.write_text(json.dumps(v,indent=2)+'\n',encoding='utf-8',newline='\n')
def main():
 rows=[('R-LCS-C11','WG14 N1570 C11 committee draft','https://www.open-std.org/jtc1/sc22/wg14/www/docs/n1570.pdf','12April2011 draft',['6.2.5 paragraph9, PDF page57: unsigned arithmetic reduction modulo one greater than maximum'],'Actual primary PDF text read through browser2026-10-18. Only this arithmetic passage is claimed; not the unavailable exact published C17 text.'),('R-LCS-PARENT','Original constrained superloop teaching and assessment','curriculum/projects/PR-T30-01.md','Current accepted teaching plus additive criterion source',['curriculum/modules/T30.md: T30.01–T30.02 teaching and environment limits','curriculum/projects/PR-T30-01.md: full contract, inputs, steps, failure and transfer','fixtures/embedded/PR-T30-01.json: complete original2/7/1 and2/2/1 input and expected values','curriculum/v5/expansion/legacy_assessments/PR-T30-01.json: all six original criteria and delayed tasks','assessor/legacy_depth/PR-T30-01.md: complete six causal notes'],'Actual named source passages read; historical receipts and learner performance are not newly assessed.')]
 resources=[]
 for rid,title,url,edition,locators,limits in rows:resources.append({'id':rid,'title':title,'authors':['WG14 or original curriculum authors'],'url':url,'edition':edition,'domains':['T30'],'kind':'documentation','access':'Actual bounded primary/source passages inspected','role':'primary','assignable':True,'reason':'Separate ISO arithmetic, original scheduling assumptions and evidence of completed changed-condition mechanisms.','prerequisites':['T20','T21','T29'],'locators':locators,'inspection':{'date':'2026-10-18','method':'Actual displayed primary PDF passage and complete named local teaching/criterion passages read.','scope':'; '.join(locators),'limits':limits}})
 write(BASE/'resources.json',{'schema_version':1,'resources':resources,'reference_gaps':['Exact published C17 remains unreadable/unavailable; N1570 is labeled C11.','No physical MCU timing or asynchronous ISR integration is inferred from the serialized host core.']})
 paths=['curriculum/modules/T30.md','curriculum/projects/PR-T30-01.md','fixtures/embedded/PR-T30-01.json','assessor/legacy_depth/PR-T30-01.md']
 write(BASE/'source_access.json',{'schema_version':1,'date':'2026-10-18','actual_primary_url':rows[0][2],'actual_passage':rows[0][4],'inspected_paths':{p:sha(ROOT/p) for p in paths},'original_course_analysis':'Unit-cost response, copied-byte continuation, finite queue and release admission, and budgeted HABC proofs are original explicit course models. They are not attributed to an uninspected RTOS or scheduling theorem.','limits':'Source inspection is author work, not independent human review, target execution or learner assessment.'})
 write(BASE/'research_gate.json',{'status':'passage-inspected','domains':['T30'],'inspection_kind':'Author passage inspection, not independent human review','research_input_sha256':{p.relative_to(ROOT).as_posix():sha(p) for p in (BASE/'resources.json',BASE/'source_access.json')}})
 print(json.dumps({'resources':len(resources)}))
if __name__=='__main__':main()
